function drawFire(f,t){if(f.put){pixelRect(f.x-10,f.y+6,20,5,'#353435');pixelRect(f.x-5,f.y+7,4,2,'#a1a198');return}const pulse=Math.sin(t*7+f.x)*2,colors=[['#ffb33e','#f26737','#b63832'],['#e3eff0','#9fc5d0','#688ba0'],['#f5d458','#b6dd56','#678841'],['#baf7ff','#65dce8','#7567ba']][f.type];ctx.globalAlpha=.6;pixelRect(f.x-15,f.y+5,30,8,'#f38231');ctx.globalAlpha=1;pixelRect(f.x-9,f.y-8+pulse,18,19,colors[2]);pixelRect(f.x-6,f.y-13+pulse,12,18,colors[1]);pixelRect(f.x-3,f.y-10+pulse,6,12,colors[0]);pixelRect(f.x-2,f.y-16+pulse,4,7,'#fff0b0');if(f.type===1){pixelRect(f.x-15,f.y-10,4,4,'#d8eeec');pixelRect(f.x+10,f.y+2,4,4,'#d8eeec')}if(f.type===2)pixelRect(f.x-14,f.y+4,5,4,'#d7e55d');if(f.type===3){pixelRect(f.x-13,f.y-12,3,3,'#fff');pixelRect(f.x+10,f.y-5,3,3,'#fff')}if(f.valve){pixelRect(f.x-17,f.y-30,34,11,'#1c2526');ctx.fillStyle=f.valve===puzzle?.step?'#ffcd70':'#b8b5a5';ctx.font='9px monospace';ctx.textAlign='center';ctx.fillText('VALVE '+f.valve,f.x,f.y-22)}}
