function drawPlayer(t){if(!player)return;const x=Math.round(player.x),y=Math.round(player.y),a=Math.atan2(mouse.y-player.y,mouse.x-player.x);pixelRect(x-9,y+8,18,6,'#392d29');pixelRect(x-8,y-7,16,17,'#e3bd45');pixelRect(x-9,y-4,5,10,'#f0d166');pixelRect(x+4,y-4,5,10,'#f0d166');pixelRect(x-6,y+7,5,6,'#624c3d');pixelRect(x+2,y+7,5,6,'#624c3d');pixelRect(x-7,y-12,14,9,'#a93230');pixelRect(x-10,y-9,20,5,'#d4493d');pixelRect(x-4,y-9,9,3,'#a8d1d1');pixelRect(x-6,y-5,12,4,'#d6b649');pixelRect(x+Math.cos(a)*11-2,y+Math.sin(a)*11-2,5,5,types[player.weapon].color);if(player.carrying){pixelRect(x-5,y+17,10,8,'#dfc19d');pixelRect(x-6,y+14,12,3,'#a93230')}if(player.invuln>0&&Math.floor(t*20)%2===0)ctx.strokeStyle='#fff';if(mouse.down||keys[' ']){ctx.strokeStyle=types[player.weapon].color;ctx.globalAlpha=.28;ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(mouse.x,mouse.y);ctx.stroke();ctx.globalAlpha=1}}
function draw(t){ctx.save();if(camShake>0)ctx.translate(rnd(-camShake,camShake),rnd(-camShake,camShake));drawFloor();if(!player){ctx.restore();return}
