for(const f of fires)drawFire(f,t);for(const e of enemies)drawEnemy(e,t);for(const c of civilians)drawCivilian(c,t);drawPlayer(t);for(const p of particles){ctx.globalAlpha=clamp(p.life/p.max,0,1);pixelRect(p.x,p.y,p.size,p.size,p.color)}ctx.globalAlpha=1;
if(gameState==='playing'){ctx.fillStyle='#d2c4a8';ctx.font='10px monospace';ctx.textAlign='left';const near=civilians.some(c=>c.state==='waiting'&&dist(player,c)<42);if(near)ctx.fillText('E  RESCUE',player.x-32,player.y-28);else if(player.carrying&&dist(player,exit)<70)ctx.fillText('STAIRWELL →',player.x-35,player.y-28);else if(puzzle&&!puzzle.open&&fires.some(f=>f.valve===puzzle.step&&f.put&&dist(player,f)<64))ctx.fillText('E  SET VALVE',player.x-35,player.y-28)}ctx.restore()}

